import unittest

from reports import export_csv


class ExportCsvExtraTests(unittest.TestCase):
    def test_one_shot_generators(self):
        rows = ({"a": i, "b": None} for i in range(3))
        cols = (c for c in ["a", "b"])
        self.assertEqual(export_csv(rows, cols), "a,b\r\n0,\r\n1,\r\n2,\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], [1])

    def test_embedded_newlines_and_unicode(self):
        rows = [{"t": "line1\nline2\r\nend", "u": "caf\u00e9"}]
        self.assertEqual(export_csv(rows, ["t", "u"]),
                         't,u\r\n"line1\nline2\r\nend",caf\u00e9\r\n')

    def test_missing_and_none_become_empty(self):
        self.assertEqual(export_csv([{"a": None}], ["a", "b"]), "a,b\r\n,\r\n")

    def test_values_str_coercion_and_ignoring_unselected(self):
        rows = [{"a": 1.5, "b": "ignored"}]
        self.assertEqual(export_csv(rows, ["a"]), "a\r\n1.5\r\n")

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
    unittest.main()
